/* @autogenerated */
import { Shift, Projected } from '@shared/data/repository/repository.model';
import {
  ObservedIssueFilter,
  ObservedIssueTypes,
} from 'app/features/observe/observed-issue/model/observed-issue.model';
import { ObservedIssueRepository } from 'app/features/observe/observed-issue/repository/observed-issue-repository.service';
import { ListViewCardTemplate, ListViewRowTemplate } from '@shared/toolkit/list-view/list-view.directives';
import { FormControl } from '@angular/forms';
import { contentChild, input, effect, Component, signal } from '@angular/core';
import { DisplayProvider } from '@shared/data/display-provider';

@Component({
  selector: 'observed-issue-view-list',
  templateUrl: './observed-issue-view-list.component.html',
  styleUrls: ['./observed-issue-view-list.component.scss'],
  standalone: false,
})
export class ObservedIssueViewListComponent {
  filters = input<ObservedIssueFilter>();
  actionName = input<string>('observed-issue');
  fixed = input<{ [key: string]: any }>();
  hidden = input<{ [key: string]: any }>();
  /** Estructura de fila o tarjeta que pasa quien usa el listado (`<list-view-row>`/`<list-view-card>` como contenido). */
  rowLayout = contentChild(ListViewRowTemplate);
  cardLayout = contentChild(ListViewCardTemplate);
  search = new FormControl<any>(undefined);
  showSearchLabel = signal('Refresh');
  hideSearchLabel = signal('Refresh');
  readonly list: Shift<Projected<ObservedIssueTypes, 'origin'>[], ObservedIssueFilter>;
  readonly displayer: DisplayProvider<any>;
  refreshDataLabel = signal('Refresh');
  /** Último filtro buscado, sin paginación: lo usa la exportación. */
  query = signal<ObservedIssueFilter>({});

  constructor(repository: ObservedIssueRepository) {
    this.displayer = repository.displayProvider();
    this.list = repository.projections(['origin']);
    effect(() => {
      setTimeout(() => this.makeSearch());
    });
  }
  makeSearch() {
    const result = { limit: 10 } as any;
    const filter = this.search.value;
    const external = this.filters();
    if (external?.search) {
      result.search = external.search;
    }
    if (external?.origin) {
      result.origin = external.origin;
    }
    if (external?.status) {
      result.status = external.status;
    }
    if (external?.level) {
      result.level = external.level;
    }
    if (external?.fingerprint) {
      result.fingerprint = external.fingerprint;
    }
    if (external?.kind) {
      result.kind = external.kind;
    }
    if (external?.title) {
      result.title = external.title;
    }
    if (filter?.search) {
      result.search = filter.search;
    }
    if (filter?.origin?.$ref) {
      result.origin = filter.origin.$ref;
    }
    if (filter?.status) {
      result.status = filter.status;
    }
    if (filter?.level) {
      result.level = filter.level;
    }
    if (filter?.fingerprint) {
      result.fingerprint = filter.fingerprint;
    }
    if (filter?.kind) {
      result.kind = filter.kind;
    }
    if (filter?.title) {
      result.title = filter.title;
    }
    if (filter?.order) {
      result.order = filter.order;
    }
    const { limit, ...query } = result;
    this.query.set(query);
    this.list.fetch(result);
  }

  next() {
    this.list.next();
  }

  reload() {
    this.list.reset();
  }

  prev() {
    console.log('PREV');
  }
}
